async function financeApi(action,payload={}){
  const {data:{session:s}}=await sb.auth.getSession();
  const r=await fetch(`${EDGE}/finance-action`,{method:'POST',headers:{'content-type':'application/json','Authorization':`Bearer ${s.access_token}`},body:JSON.stringify({action,...payload})});
  const d=await r.json();if(!r.ok)throw Error(d.error||'Finance action failed');return d;
}
async function financeWorkspace(el){
  const eventId=await getEventId();
  const [{data:ready,error},{data:rates},{data:invoices},{data:sponsorRows}]=await Promise.all([
    sb.from('v_invoice_readiness').select('*').order('surname'),
    sb.from('rate_card').select('id,rate_code,description,unit,unit_price,status,charge_category').eq('event_id',eventId).order('charge_category').order('rate_code'),
    sb.from('invoices').select('id,invoice_reference,invoice_type,status,gross_total,net_total,vat_total,issue_date,due_date,payment_link,attendee_id,billing_account_organisation_id,attendees(first_name,surname),organisations(organisation_name)').order('created_at',{ascending:false}).limit(50),
    sb.from('event_sponsors').select('organisation_id,consolidated_invoice_requested,organisations(id,organisation_name)').eq('event_id',eventId).eq('active',true)
  ]);
  if(error){el.innerHTML=`<div class="notice error">${esc(error.message)}</div>`;return}
  const orgs=(sponsorRows||[]).filter(x=>x.consolidated_invoice_requested).map(x=>x.organisations).filter(Boolean);
  el.innerHTML=`<div class="toolbar"><div><h2>Finance</h2><p class="lead">Readiness, approved rate cards, invoice review and payment status from confirmed canonical data.</p></div><div class="rowactions">${orgs.length?'<button class="btn secondary" id="buildConsolidated">Build sponsor invoice</button>':''}</div></div>
  <div class="statgrid"><div class="stat"><small>Ready for invoice</small><strong>${ready?.filter(x=>x.ready_for_invoice).length||0}</strong></div><div class="stat"><small>Not ready</small><strong>${ready?.filter(x=>!x.ready_for_invoice).length||0}</strong></div><div class="stat"><small>Proposed rates</small><strong>${rates?.filter(x=>x.status==='proposed').length||0}</strong></div><div class="stat"><small>Invoices</small><strong>${invoices?.length||0}</strong></div></div>
  <h3>Invoice readiness</h3>${ready?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Attendee</th><th>Accommodation</th><th>Lift pass</th><th>Checked</th><th>Status</th><th>Action</th></tr></thead><tbody>${ready.map(r=>`<tr><td><b>${esc(r.first_name)} ${esc(r.surname)}</b><div class="meta">${esc(r.category)}</div></td><td>${r.accommodation_confirmed?'✓':'—'}</td><td>${r.lift_pass_confirmed?'✓':'—'}</td><td>${r.data_checked?'✓':'—'}</td><td><span class="pill ${r.ready_for_invoice?'green':'amber'}">${r.ready_for_invoice?'Ready':'Hold'}</span></td><td>${r.ready_for_invoice?`<button class="btn small primary" data-invoice="${r.attendee_id}">Build draft</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No attendees yet.</div>'}
  <h3 style="margin-top:26px">Invoices</h3>${invoices?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Reference</th><th>Bill to</th><th>Type</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody>${invoices.map(i=>`<tr><td><b>${esc(i.invoice_reference)}</b><div class="meta">${esc(i.issue_date||'Not issued')}</div></td><td>${esc(i.attendees?`${i.attendees.first_name||''} ${i.attendees.surname||''}`:i.organisations?.organisation_name||'—')}</td><td>${esc(i.invoice_type.replaceAll('_',' '))}</td><td><span class="pill ${i.status==='paid'?'green':i.status==='issued'?'amber':''}">${esc(i.status)}</span></td><td>£${Number(i.gross_total||0).toFixed(2)}</td><td><button class="btn small secondary" data-manage-invoice="${i.id}">Manage</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No invoices built yet.</div>'}
  <h3 style="margin-top:26px">2027 rate card</h3><div class="tablewrap"><table class="data"><thead><tr><th>Code</th><th>Description</th><th>Unit</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody>${(rates||[]).map(r=>`<tr><td>${esc(r.rate_code)}</td><td>${esc(r.description)}</td><td>${esc(r.unit)}</td><td>£${Number(r.unit_price).toFixed(2)}</td><td><span class="pill ${r.status==='approved'?'green':'amber'}">${esc(r.status)}</span></td><td><button class="btn small secondary" data-rate="${r.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`;
  document.querySelectorAll('[data-invoice]').forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent='Building…';const {data:{session:s}}=await sb.auth.getSession();const r=await fetch(`${EDGE}/finance-build-invoice`,{method:'POST',headers:{'content-type':'application/json','Authorization':`Bearer ${s.access_token}`},body:JSON.stringify({attendee_id:b.dataset.invoice})});const d=await r.json();if(!r.ok){alert(d.error||'Unable to build invoice');b.disabled=false;b.textContent='Build draft';return}financeWorkspace(el);});
  document.querySelectorAll('[data-manage-invoice]').forEach(b=>{const inv=invoices.find(i=>i.id===b.dataset.manageInvoice);b.onclick=()=>invoiceFinanceModal(inv,el);});
  document.querySelectorAll('[data-rate]').forEach(b=>{const rate=rates.find(r=>r.id===b.dataset.rate);b.onclick=()=>rateFinanceModal(rate,el);});
  if(document.querySelector('#buildConsolidated'))document.querySelector('#buildConsolidated').onclick=()=>consolidatedInvoiceModal(eventId,orgs,el);
}
function rateFinanceModal(rate,el){
  const m=modal(`<h2>${esc(rate.rate_code)}</h2><p class="lead">${esc(rate.description)}</p><form id="rateForm"><div class="formgrid"><label class="field"><span>Unit price</span><input name="unit_price" type="number" min="0" step="0.01" value="${Number(rate.unit_price).toFixed(2)}" required></label><label class="field"><span>Status</span><select name="status"><option value="proposed" ${rate.status==='proposed'?'selected':''}>Proposed</option><option value="approved" ${rate.status==='approved'?'selected':''}>Approved</option><option value="inactive" ${rate.status==='inactive'?'selected':''}>Inactive</option></select></label></div><div id="rateMsg"></div><div class="actions"><button class="btn primary">Save rate</button></div></form>`);
  m.querySelector('#rateForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await financeApi('update_rate',{rate_id:rate.id,unit_price:fd.get('unit_price'),status:fd.get('status')});m.remove();financeWorkspace(el)}catch(err){m.querySelector('#rateMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}};
}
async function invoiceFinanceModal(inv,el){
  const {data:detail,error}=await sb.from('invoices').select('id,event_id,invoice_reference,invoice_type,status,net_total,vat_total,gross_total,issue_date,due_date,payment_link,attendee_id,billing_account_organisation_id,attendees(first_name,surname,email),organisations(organisation_name,billing_name,billing_address_1,billing_address_2,town_city,county_region,postcode,country,billing_email),invoice_lines(id,description,quantity,unit_price,net_amount,vat_amount,gross_amount,rate_code)').eq('id',inv.id).single();
  if(error){alert(error.message);return}
  inv=detail;
  const statuses=['draft','awaiting_billing_update','ready_for_review','approved','issued','paid','cancelled','void'];
  const lines=inv.invoice_lines||[];
  const m=modal(`<h2>${esc(inv.invoice_reference)}</h2><div class="statgrid mini"><div class="stat"><small>Net</small><strong>£${Number(inv.net_total||0).toFixed(2)}</strong></div><div class="stat"><small>VAT</small><strong>£${Number(inv.vat_total||0).toFixed(2)}</strong></div><div class="stat"><small>Gross</small><strong>£${Number(inv.gross_total||0).toFixed(2)}</strong></div></div><div class="actions"><button class="btn secondary" id="printInvoice">Print / Save PDF</button></div><h3>Invoice lines</h3>${lines.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Net</th><th>VAT</th><th>Gross</th></tr></thead><tbody>${lines.map(x=>`<tr><td>${esc(x.description)}<div class="meta">${esc(x.rate_code||'')}</div></td><td>${Number(x.quantity||0)}</td><td>£${Number(x.unit_price||0).toFixed(2)}</td><td>£${Number(x.net_amount||0).toFixed(2)}</td><td>£${Number(x.vat_amount||0).toFixed(2)}</td><td><b>£${Number(x.gross_amount||0).toFixed(2)}</b></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No invoice lines.</div>'}<hr class="sep"><form id="invoiceMetaForm"><div class="formgrid"><label class="field"><span>Due date</span><input name="due_date" type="date" value="${esc(inv.due_date||'')}"></label><label class="field wide"><span>Payment link</span><input name="payment_link" type="url" value="${esc(inv.payment_link||'')}"></label></div><div class="actions"><button class="btn secondary">Save payment details</button></div></form><hr class="sep"><form id="invoiceStatusForm"><div class="formgrid"><label class="field"><span>Invoice status</span><select name="status">${statuses.map(x=>`<option value="${x}" ${inv.status===x?'selected':''}>${esc(x.replaceAll('_',' '))}</option>`).join('')}</select></label></div><div class="notice warn">Status transitions are validated by the billing engine. Issued and paid invoices are locked against financial changes.</div><div class="actions"><button class="btn primary">Change status</button></div></form><hr class="sep"><form id="adjustmentForm"><h3>Add approved adjustment</h3><div class="formgrid"><label class="field"><span>Type</span><select name="adjustment_type"><option value="fixed">Fixed amount</option><option value="percentage">Percentage</option></select></label><label class="field"><span>Direction</span><select name="direction"><option value="discount">Discount</option><option value="increase">Increase</option></select></label><label class="field"><span>Value</span><input name="value" type="number" min="0" step="0.01" required></label><label class="field wide"><span>Description</span><input name="description" required></label></div><div id="invoiceMsg"></div><div class="actions"><button class="btn secondary">Add adjustment</button></div></form>`);
  m.querySelector('#printInvoice').onclick=()=>printInvoice(inv);
  m.querySelector('#invoiceMetaForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await financeApi('update_payment',{invoice_id:inv.id,due_date:fd.get('due_date')||null,payment_link:fd.get('payment_link')||null});m.remove();financeWorkspace(el)}catch(err){alert(err.message)}};
  m.querySelector('#invoiceStatusForm').onsubmit=async e=>{e.preventDefault();const status=new FormData(e.currentTarget).get('status');try{await financeApi('set_invoice_status',{invoice_id:inv.id,status});m.remove();financeWorkspace(el)}catch(err){alert(err.message)}};
  m.querySelector('#adjustmentForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await financeApi('adjustment',{invoice_id:inv.id,attendee_id:inv.attendee_id||null,adjustment_type:fd.get('adjustment_type'),direction:fd.get('direction'),value:fd.get('value'),description:fd.get('description')});m.remove();financeWorkspace(el)}catch(err){m.querySelector('#invoiceMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}};
}
function printInvoice(inv){
  const org=inv.organisations||{};const person=inv.attendees||{};const billTo=org.organisation_name||[person.first_name,person.surname].filter(Boolean).join(' ')||'Attendee';
  const address=[org.billing_name&&org.billing_name!==billTo?org.billing_name:null,org.billing_address_1,org.billing_address_2,org.town_city,org.county_region,org.postcode,org.country].filter(Boolean).map(esc).join('<br>');
  const rows=(inv.invoice_lines||[]).map(x=>`<tr><td>${esc(x.description)}</td><td class="n">${Number(x.quantity||0)}</td><td class="n">£${Number(x.unit_price||0).toFixed(2)}</td><td class="n">£${Number(x.net_amount||0).toFixed(2)}</td><td class="n">£${Number(x.vat_amount||0).toFixed(2)}</td><td class="n">£${Number(x.gross_amount||0).toFixed(2)}</td></tr>`).join('');
  const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(inv.invoice_reference)}</title><style>body{font-family:Arial,sans-serif;color:#10202f;margin:42px;font-size:13px}header{border-bottom:4px solid #12395a;padding-bottom:18px;margin-bottom:28px}h1{margin:0;font-size:28px}.meta{color:#637282}.grid{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:24px 0}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left}.n{text-align:right}.totals{margin-left:auto;width:330px;margin-top:18px}.totals div{display:flex;justify-content:space-between;padding:6px}.gross{font-size:18px;font-weight:700;border-top:2px solid #12395a}.footer{margin-top:48px;font-size:11px;color:#637282}@media print{body{margin:18mm}}</style></head><body><header><h1>UKAF WSA · ISSSC 2027</h1><div class="meta">Invoice ${esc(inv.invoice_reference)}</div></header><div class="grid"><div><b>Bill to</b><p>${esc(billTo)}${address?`<br>${address}`:''}${org.billing_email?`<br>${esc(org.billing_email)}`:''}</p></div><div><b>Status</b><p>${esc(inv.status)}</p><b>Issue date</b><p>${esc(inv.issue_date||'Not issued')}</p><b>Due date</b><p>${esc(inv.due_date||'—')}</p></div></div><table><thead><tr><th>Description</th><th class="n">Qty</th><th class="n">Unit</th><th class="n">Net</th><th class="n">VAT</th><th class="n">Gross</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><div><span>Net</span><b>£${Number(inv.net_total||0).toFixed(2)}</b></div><div><span>VAT</span><b>£${Number(inv.vat_total||0).toFixed(2)}</b></div><div class="gross"><span>Total</span><span>£${Number(inv.gross_total||0).toFixed(2)}</span></div></div>${inv.payment_link?`<p><b>Payment link:</b> ${esc(inv.payment_link)}</p>`:''}<div class="footer">Inter Service Snow Sports Championships · UK Armed Forces Winter Sports Association</div></body></html>`;
  const w=window.open('','_blank');if(!w){alert('Please allow pop-ups to print the invoice.');return}w.document.open();w.document.write(html);w.document.close();setTimeout(()=>w.print(),250);
}

function consolidatedInvoiceModal(eventId,orgs,el){
  const m=modal(`<h2>Build consolidated sponsor invoice</h2><p class="lead">All attendees billed to the selected organisation must be ready for invoicing.</p><form id="consolidatedForm"><label class="field"><span>Billing organisation</span><select name="organisation_id" required><option value="">Select</option>${orgs.map(o=>`<option value="${o.id}">${esc(o.organisation_name)}</option>`).join('')}</select></label><div id="consolidatedMsg"></div><div class="actions"><button class="btn primary">Build / rebuild invoice</button></div></form>`);
  m.querySelector('#consolidatedForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await financeApi('build_consolidated',{event_id:eventId,organisation_id:fd.get('organisation_id')});m.remove();financeWorkspace(el)}catch(err){m.querySelector('#consolidatedMsg').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}};
}

async function uploadPublicAsset(file,folder){
  if(!file||!file.name)return null;
  const safe=file.name.toLowerCase().replace(/[^a-z0-9._-]+/g,'-').replace(/^-+|-+$/g,'');
  const path=`${folder}/${Date.now()}-${safe||'file'}`;
  const {error}=await sb.storage.from('isssc-public').upload(path,file,{upsert:false,contentType:file.type||undefined});
  if(error)throw error;
  return sb.storage.from('isssc-public').getPublicUrl(path).data.publicUrl;
}
async function contentWorkspace(el){
  const eventId=await getEventId();
  const [{data:ann},{data:sched},{data:venues},{data:bios},{data:docs},{data:plans},{data:tables},{data:attendees},{data:assignments}]=await Promise.all([
    sb.from('announcements').select('*').eq('event_id',eventId).order('publish_at',{ascending:false}),
    sb.from('schedule_items').select('*').eq('event_id',eventId).order('starts_at'),
    sb.from('venues').select('*').eq('event_id',eventId).order('name'),
    sb.from('biographies').select('*').eq('event_id',eventId).order('sort_order'),
    sb.from('event_documents').select('*').eq('event_id',eventId).order('created_at',{ascending:false}),
    sb.from('table_plans').select('*').eq('event_id',eventId).order('event_date',{ascending:false}),
    sb.from('seating_tables').select('id,table_name,capacity,published,schedule_item_id,schedule_items(title,starts_at)').eq('event_id',eventId).order('sort_order'),
    sb.from('attendees').select('id,first_name,surname,category').eq('event_id',eventId).order('surname'),
    sb.from('seating_assignments').select('id,seating_table_id,attendee_id,seat_label,attendees(first_name,surname),seating_tables(table_name)')
  ]);
  const counts=Object.fromEntries((tables||[]).map(t=>[t.id,(assignments||[]).filter(a=>a.seating_table_id===t.id).length]));
  el.innerHTML=`<div class="toolbar"><div><h2>Event content</h2><p class="lead">Publish the live programme, people, documents, venues and seating from one controlled source.</p></div><div class="rowactions"><button class="btn primary" id="addAnn">Update</button><button class="btn secondary" id="addSchedule">Programme</button><button class="btn secondary" id="addVenue">Venue</button><button class="btn secondary" id="addBio">Biography</button><button class="btn secondary" id="addDoc">Document</button><button class="btn secondary" id="addPlan">Table plan</button><button class="btn secondary" id="addTable">Seating table</button>${tables?.length&&attendees?.length?'<button class="btn secondary" id="assignSeat">Assign seat</button>':''}</div></div>
  <div class="statgrid"><div class="stat"><small>Announcements</small><strong>${ann?.length||0}</strong></div><div class="stat"><small>Programme items</small><strong>${sched?.length||0}</strong></div><div class="stat"><small>Biographies</small><strong>${bios?.length||0}</strong></div><div class="stat"><small>Seating tables</small><strong>${tables?.length||0}</strong></div></div>
  <h3>Announcements</h3>${ann?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Title</th><th>Priority</th><th>Published</th><th>Publish time</th><th></th></tr></thead><tbody>${ann.map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.priority)}</td><td>${a.published?'Yes':'No'}</td><td>${fmt(a.publish_at)}</td><td><button class="btn small secondary" data-edit-ann="${a.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No announcements yet.</div>'}
  <h3 style="margin-top:24px">Programme</h3>${sched?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Item</th><th>Category</th><th>Starts</th><th>Published</th><th></th></tr></thead><tbody>${sched.map(s=>`<tr><td>${esc(s.title)}</td><td>${esc(s.category||'')}</td><td>${fmt(s.starts_at)}</td><td>${s.published?'Yes':'No'}</td><td><button class="btn small secondary" data-edit-sched="${s.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No programme items yet.</div>'}
  <div class="grid two" style="margin-top:24px"><div><h3>Venues</h3>${venues?.length?`<div class="card">${venues.map(v=>`<div class="doc"><div><b>${esc(v.name)}</b><div class="meta">${esc(v.venue_type||'')}</div></div><button class="btn small secondary" data-edit-venue="${v.id}">Edit</button></div>`).join('')}</div>`:'<div class="empty">No venues yet.</div>'}</div><div><h3>Biographies</h3>${bios?.length?`<div class="card">${bios.map(b=>`<div class="doc"><div><b>${esc(b.display_name)}</b><div class="meta">${esc(b.role_title||'')} · ${b.published?'Published':'Draft'}</div></div><button class="btn small secondary" data-toggle-content="biographies:${b.id}:${b.published?'0':'1'}">${b.published?'Unpublish':'Publish'}</button></div>`).join('')}</div>`:'<div class="empty">No biographies yet.</div>'}</div></div>
  <div class="grid two" style="margin-top:24px"><div><h3>Documents</h3>${docs?.length?`<div class="card">${docs.map(d=>`<div class="doc"><div><b>${esc(d.title)}</b><div class="meta">${esc(d.category||'Document')} · ${d.published?'Published':'Draft'}</div></div><button class="btn small secondary" data-toggle-content="event_documents:${d.id}:${d.published?'0':'1'}">${d.published?'Unpublish':'Publish'}</button></div>`).join('')}</div>`:'<div class="empty">No documents yet.</div>'}</div><div><h3>Table plans</h3>${plans?.length?`<div class="card">${plans.map(p=>`<div class="doc"><div><b>${esc(p.title)}</b><div class="meta">${esc(p.event_date||'')} · v${esc(p.version)} · ${p.published?'Published':'Draft'}</div></div><button class="btn small secondary" data-toggle-content="table_plans:${p.id}:${p.published?'0':'1'}">${p.published?'Unpublish':'Publish'}</button></div>`).join('')}</div>`:'<div class="empty">No table plans yet.</div>'}</div></div>
  <h3 style="margin-top:24px">Structured seating</h3>${tables?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Table</th><th>Event</th><th>Capacity</th><th>Assigned</th><th>Published</th><th></th></tr></thead><tbody>${tables.map(t=>`<tr><td><b>${esc(t.table_name)}</b></td><td>${esc(t.schedule_items?.title||'General')}</td><td>${esc(t.capacity??'—')}</td><td>${counts[t.id]||0}</td><td>${t.published?'Yes':'No'}</td><td><button class="btn small secondary" data-toggle-content="seating_tables:${t.id}:${t.published?'0':'1'}">${t.published?'Unpublish':'Publish'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No seating tables yet.</div>'}
  <h3 style="margin-top:24px">Seat assignments</h3>${assignments?.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Attendee</th><th>Table</th><th>Seat</th><th></th></tr></thead><tbody>${assignments.map(a=>`<tr><td>${esc(a.attendees?`${a.attendees.first_name||''} ${a.attendees.surname||''}`:'Attendee')}</td><td>${esc(a.seating_tables?.table_name||'—')}</td><td>${esc(a.seat_label||'—')}</td><td><button class="btn small secondary" data-unassign="${a.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No seat assignments yet.</div>'}`;
  document.querySelector('#addAnn').onclick=()=>contentModal('announcement',eventId,el,{sched,tables,attendees});
  document.querySelector('#addSchedule').onclick=()=>contentModal('schedule',eventId,el,{sched,tables,attendees});
  document.querySelector('#addVenue').onclick=()=>contentModal('venue',eventId,el,{sched,tables,attendees});
  document.querySelector('#addBio').onclick=()=>contentModal('biography',eventId,el,{sched,tables,attendees});
  document.querySelector('#addDoc').onclick=()=>contentModal('document',eventId,el,{sched,tables,attendees});
  document.querySelector('#addPlan').onclick=()=>contentModal('tableplan',eventId,el,{sched,tables,attendees});
  document.querySelector('#addTable').onclick=()=>contentModal('seating',eventId,el,{sched,tables,attendees});
  if(document.querySelector('#assignSeat'))document.querySelector('#assignSeat').onclick=()=>contentModal('assignment',eventId,el,{sched,tables,attendees});
  document.querySelectorAll('[data-edit-ann]').forEach(b=>b.onclick=()=>editCoreContent('announcement',ann.find(x=>x.id===b.dataset.editAnn),el));
  document.querySelectorAll('[data-edit-sched]').forEach(b=>b.onclick=()=>editCoreContent('schedule',sched.find(x=>x.id===b.dataset.editSched),el));
  document.querySelectorAll('[data-edit-venue]').forEach(b=>b.onclick=()=>editCoreContent('venue',venues.find(x=>x.id===b.dataset.editVenue),el));
  document.querySelectorAll('[data-toggle-content]').forEach(b=>b.onclick=async()=>{const [table,id,val]=b.dataset.toggleContent.split(':');b.disabled=true;const {error}=await sb.from(table).update({published:val==='1'}).eq('id',id);if(error){alert(error.message);b.disabled=false;return}eventData=null;contentWorkspace(el);});
  document.querySelectorAll('[data-unassign]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this seating assignment?'))return;b.disabled=true;const {error}=await sb.from('seating_assignments').delete().eq('id',b.dataset.unassign);if(error){alert(error.message);b.disabled=false;return}contentWorkspace(el);});
}
function inputDateTime(v){if(!v)return '';const d=new Date(v);const off=d.getTimezoneOffset();return new Date(d.getTime()-off*60000).toISOString().slice(0,16);}
function editCoreContent(type,item,el){
  if(!item)return;
  const forms={
    announcement:`<h2>Edit announcement</h2><form id="editCoreForm"><div class="formgrid"><label class="field wide"><span>Title</span><input name="title" value="${esc(item.title)}" required></label><label class="field"><span>Priority</span><select name="priority"><option ${item.priority==='normal'?'selected':''}>normal</option><option ${item.priority==='high'?'selected':''}>high</option><option ${item.priority==='urgent'?'selected':''}>urgent</option></select></label><label class="check"><input name="published" type="checkbox" ${item.published?'checked':''}> Published</label><label class="field wide"><span>Message</span><textarea name="body" required>${esc(item.body||'')}</textarea></label></div><div class="actions"><button class="btn primary">Save changes</button></div></form>`,
    schedule:`<h2>Edit programme item</h2><form id="editCoreForm"><div class="formgrid"><label class="field wide"><span>Title</span><input name="title" value="${esc(item.title)}" required></label><label class="field"><span>Category</span><input name="category" value="${esc(item.category||'')}"></label><label class="field"><span>Starts</span><input name="starts_at" type="datetime-local" value="${inputDateTime(item.starts_at)}" required></label><label class="field"><span>Ends</span><input name="ends_at" type="datetime-local" value="${inputDateTime(item.ends_at)}"></label><label class="check"><input name="published" type="checkbox" ${item.published?'checked':''}> Published</label><label class="field wide"><span>Description</span><textarea name="description">${esc(item.description||'')}</textarea></label></div><div class="actions"><button class="btn primary">Save changes</button></div></form>`,
    venue:`<h2>Edit venue</h2><form id="editCoreForm"><div class="formgrid"><label class="field"><span>Name</span><input name="name" value="${esc(item.name)}" required></label><label class="field"><span>Type</span><input name="venue_type" value="${esc(item.venue_type||'')}"></label><label class="field wide"><span>Address</span><input name="address" value="${esc(item.address||'')}"></label><label class="field wide"><span>Directions</span><textarea name="directions_text">${esc(item.directions_text||'')}</textarea></label><label class="field wide"><span>Map URL</span><input name="map_url" type="url" value="${esc(item.map_url||'')}"></label><label class="check"><input name="active" type="checkbox" ${item.active!==false?'checked':''}> Active</label></div><div class="actions"><button class="btn primary">Save changes</button></div></form>`
  };
  const m=modal(forms[type]);
  m.querySelector('#editCoreForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);let table,record;if(type==='announcement'){table='announcements';record={title:fd.get('title'),body:fd.get('body'),priority:fd.get('priority'),published:fd.get('published')==='on'};}if(type==='schedule'){table='schedule_items';record={title:fd.get('title'),category:fd.get('category')||null,starts_at:fd.get('starts_at'),ends_at:fd.get('ends_at')||null,description:fd.get('description')||null,published:fd.get('published')==='on'};}if(type==='venue'){table='venues';record={name:fd.get('name'),venue_type:fd.get('venue_type')||null,address:fd.get('address')||null,directions_text:fd.get('directions_text')||null,map_url:fd.get('map_url')||null,active:fd.get('active')==='on'};}const {error}=await sb.from(table).update(record).eq('id',item.id);if(error){alert(error.message);return}m.remove();eventData=null;contentWorkspace(el);};
}
function contentModal(type,eventId,el,ctx={}){
  const scheduleOptions=`<option value="">No linked programme item</option>${(ctx.sched||[]).map(s=>`<option value="${s.id}">${esc(s.title)} · ${fmt(s.starts_at)}</option>`).join('')}`;
  const tableOptions=`<option value="">Select table</option>${(ctx.tables||[]).map(t=>`<option value="${t.id}">${esc(t.table_name)}${t.schedule_items?.title?' · '+esc(t.schedule_items.title):''}</option>`).join('')}`;
  const attendeeOptions=`<option value="">Select attendee</option>${(ctx.attendees||[]).map(a=>`<option value="${a.id}">${esc(a.surname)}, ${esc(a.first_name)} · ${esc(a.category||'')}</option>`).join('')}`;
  const forms={
    announcement:`<h2>New announcement</h2><form id="contentForm"><div class="formgrid"><label class="field wide"><span>Title</span><input name="title" required></label><label class="field"><span>Priority</span><select name="priority"><option>normal</option><option>high</option><option>urgent</option></select></label><label class="check"><input name="published" type="checkbox" checked> Publish now</label><label class="field wide"><span>Message</span><textarea name="body" required></textarea></label></div><div class="actions"><button class="btn primary">Save</button></div></form>`,
    schedule:`<h2>New programme item</h2><form id="contentForm"><div class="formgrid"><label class="field wide"><span>Title</span><input name="title" required></label><label class="field"><span>Category</span><input name="category" placeholder="Race, dinner, ceremony…"></label><label class="field"><span>Starts</span><input name="starts_at" type="datetime-local" required></label><label class="field"><span>Ends</span><input name="ends_at" type="datetime-local"></label><label class="check"><input name="published" type="checkbox" checked> Publish</label><label class="field wide"><span>Description</span><textarea name="description"></textarea></label></div><div class="actions"><button class="btn primary">Save</button></div></form>`,
    venue:`<h2>New venue</h2><form id="contentForm"><div class="formgrid"><label class="field"><span>Name</span><input name="name" required></label><label class="field"><span>Type</span><input name="venue_type" placeholder="Race venue, hotel, dinner…"></label><label class="field wide"><span>Address</span><input name="address"></label><label class="field wide"><span>Directions</span><textarea name="directions_text"></textarea></label><label class="field wide"><span>Map URL</span><input name="map_url" type="url"></label></div><div class="actions"><button class="btn primary">Save</button></div></form>`,
    biography:`<h2>New biography</h2><form id="contentForm"><div class="formgrid"><label class="field"><span>Display name</span><input name="display_name" required></label><label class="field"><span>Role / title</span><input name="role_title"></label><label class="field"><span>Organisation</span><input name="organisation_name"></label><label class="field"><span>Photo</span><input name="photo" type="file" accept="image/*"></label><label class="field wide"><span>Biography</span><textarea name="biography"></textarea></label><label class="check"><input name="published" type="checkbox"> Publish</label></div><div class="actions"><button class="btn primary">Save biography</button></div></form>`,
    document:`<h2>New document</h2><form id="contentForm"><div class="formgrid"><label class="field"><span>Title</span><input name="title" required></label><label class="field"><span>Category</span><input name="category"></label><label class="field wide"><span>External URL</span><input name="external_url" type="url"></label><label class="field wide"><span>Or upload a file</span><input name="file" type="file" accept=".pdf,.doc,.docx,.xlsx,.xls,.png,.jpg,.jpeg"></label><label class="check"><input name="published" type="checkbox"> Publish</label></div><div class="actions"><button class="btn primary">Save document</button></div></form>`,
    tableplan:`<h2>New table plan</h2><form id="contentForm"><div class="formgrid"><label class="field wide"><span>Title</span><input name="title" required></label><label class="field"><span>Event date</span><input name="event_date" type="date"></label><label class="field"><span>Version</span><input name="version" type="number" min="1" value="1"></label><label class="field wide"><span>Plan file</span><input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg"></label><label class="field wide"><span>Notes</span><textarea name="notes"></textarea></label><label class="check"><input name="published" type="checkbox"> Publish</label></div><div class="actions"><button class="btn primary">Save table plan</button></div></form>`,
    seating:`<h2>New seating table</h2><form id="contentForm"><div class="formgrid"><label class="field"><span>Table name</span><input name="table_name" required></label><label class="field"><span>Capacity</span><input name="capacity" type="number" min="1"></label><label class="field wide"><span>Programme item</span><select name="schedule_item_id">${scheduleOptions}</select></label><label class="check"><input name="published" type="checkbox"> Publish</label><label class="field wide"><span>Notes</span><textarea name="notes"></textarea></label></div><div class="actions"><button class="btn primary">Save table</button></div></form>`,
    assignment:`<h2>Assign attendee to a table</h2><form id="contentForm"><div class="formgrid"><label class="field wide"><span>Table</span><select name="seating_table_id" required>${tableOptions}</select></label><label class="field wide"><span>Attendee</span><select name="attendee_id" required>${attendeeOptions}</select></label><label class="field"><span>Seat label</span><input name="seat_label" placeholder="Optional"></label></div><div class="actions"><button class="btn primary">Assign</button></div></form>`
  };
  const m=modal(forms[type]);
  m.querySelector('#contentForm').onsubmit=async e=>{
    e.preventDefault();const fd=new FormData(e.currentTarget);let table,record;
    try{
      if(type==='announcement'){table='announcements';record={event_id:eventId,title:fd.get('title'),body:fd.get('body'),priority:fd.get('priority'),published:fd.get('published')==='on',publish_at:new Date().toISOString(),audience:['all']};}
      if(type==='schedule'){table='schedule_items';record={event_id:eventId,title:fd.get('title'),description:fd.get('description')||null,category:fd.get('category')||null,starts_at:fd.get('starts_at'),ends_at:fd.get('ends_at')||null,published:fd.get('published')==='on',audience:['all']};}
      if(type==='venue'){table='venues';record={event_id:eventId,name:fd.get('name'),venue_type:fd.get('venue_type')||null,address:fd.get('address')||null,directions_text:fd.get('directions_text')||null,map_url:fd.get('map_url')||null,active:true};}
      if(type==='biography'){table='biographies';const photo=fd.get('photo');const photoUrl=photo?.name?await uploadPublicAsset(photo,'biographies'):null;record={event_id:eventId,display_name:fd.get('display_name'),role_title:fd.get('role_title')||null,organisation_name:fd.get('organisation_name')||null,biography:fd.get('biography')||null,photo_path:photoUrl,published:fd.get('published')==='on'};}
      if(type==='document'){table='event_documents';const file=fd.get('file');const fileUrl=file?.name?await uploadPublicAsset(file,'documents'):null;record={event_id:eventId,title:fd.get('title'),category:fd.get('category')||null,file_path:fileUrl,external_url:fd.get('external_url')||null,audience:['all'],published:fd.get('published')==='on'};}
      if(type==='tableplan'){table='table_plans';const file=fd.get('file');const fileUrl=file?.name?await uploadPublicAsset(file,'table-plans'):null;record={event_id:eventId,title:fd.get('title'),event_date:fd.get('event_date')||null,version:Number(fd.get('version')||1),file_path:fileUrl,notes:fd.get('notes')||null,published:fd.get('published')==='on'};}
      if(type==='seating'){table='seating_tables';record={event_id:eventId,table_name:fd.get('table_name'),capacity:fd.get('capacity')?Number(fd.get('capacity')):null,schedule_item_id:fd.get('schedule_item_id')||null,published:fd.get('published')==='on',notes:fd.get('notes')||null};}
      if(type==='assignment'){table='seating_assignments';record={seating_table_id:fd.get('seating_table_id'),attendee_id:fd.get('attendee_id'),seat_label:fd.get('seat_label')||null};}
      const {error}=await sb.from(table).insert(record);if(error)throw error;
      m.remove();eventData=null;contentWorkspace(el);
    }catch(err){alert(err.message||'Unable to save content')}
  };
}

async function render(route){route=route||((location.hash||'#home').slice(1));if(invitationToken&&route==='home')route='register';if(route==='event')return renderEvent();if(route==='register')return renderRegister();if(route==='mytrip')return renderMyTrip();if(route==='staff')return renderStaff();return renderHome();}

sb.auth.onAuthStateChange(async(_event,s)=>{session=s;const h=location.hash||'';if(h.includes('staff'))renderStaff();else if(h.includes('mytrip'))renderMyTrip();});
const {data:{session:initialSession}}=await sb.auth.getSession();session=initialSession;
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
render();
